@namespace sv_907d7bccc5af4b45817347eb36b57a96.Components.Pages.Board

<div class="kanban-column">
    <div class="column-header">
        <h3>@ColumnName (@Tasks.Count)</h3>
    </div>
    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      ShowMoveLeft="HasLeftColumn"
                      ShowMoveRight="HasRightColumn"
                      OnMoveLeft="() => MoveLeft(task)"
                      OnMoveRight="() => MoveRight(task)" />
        }
    </div>
    <div class="column-footer">
        @if (showAddForm)
        {
            <AddTaskForm OnSave="HandleSave" OnCancel="() => showAddForm = false" />
        }
        else
        {
            <button class="btn-add-task" @onclick="() => showAddForm = true">Add Task</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string ColumnName { get; set; } = string.Empty;
    [Parameter, EditorRequired] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool HasLeftColumn { get; set; }
    [Parameter] public bool HasRightColumn { get; set; }
    [Parameter, EditorRequired] public EventCallback<(TaskItem Task, string Direction)> OnMoveTask { get; set; }
    [Parameter, EditorRequired] public EventCallback<AddTaskForm.NewTaskModel> OnAddTask { get; set; }

    private bool showAddForm;

    private async Task MoveLeft(TaskItem task)
    {
        await OnMoveTask.InvokeAsync((task, "left"));
    }

    private async Task MoveRight(TaskItem task)
    {
        await OnMoveTask.InvokeAsync((task, "right"));
    }

    private async Task HandleSave(AddTaskForm.NewTaskModel model)
    {
        await OnAddTask.InvokeAsync(model);
        showAddForm = false;
    }
}

