arguments.old_str:
@page "/board"
@namespace sv_907d7bccc5af4b45817347eb36b57a96.Components.Pages.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

@if (isLoading)
{
    <p class="board-loading">Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <p class="board-error">Error: @errorMessage</p>
}
else
{
    <BoardStats Tasks="allTasks" />
    <BoardSearchBar SearchText="@searchText" OnSearchChanged="HandleSearchChanged" />

    <div class="kanban-board">
        <KanbanColumn ColumnName="To Do"
                      Tasks="GetFilteredTasks("To Do")"
                      HasLeftColumn="false"
                      HasRightColumn="true"
                      OnMoveTask="HandleMoveTask"
                      OnAddTask="model => HandleAddTask(model, "To Do")" />

        <KanbanColumn ColumnName="In Progress"
                      Tasks="GetFilteredTasks("In Progress")"
                      HasLeftColumn="true"
                      HasRightColumn="true"
                      OnMoveTask="HandleMoveTask"
                      OnAddTask="model => HandleAddTask(model, "In Progress")" />

        <KanbanColumn ColumnName="Done"
                      Tasks="GetFilteredTasks("Done")"
                      HasLeftColumn="true"
                      HasRightColumn="false"
                      OnMoveTask="HandleMoveTask"
                      OnAddTask="model => HandleAddTask(model, "Done")" />
    </div>
}

